# STT pipeline: VAD -> decode -> endpointing (partial results stream)
def vad(chunk):
    return sum(abs(b - 128) for b in chunk) / len(chunk) > 20  # toy energy VAD

def decode(chunks):  # the recognizer (real: Whisper/Conformer)
    return ' '.join('word%d' % i for i, _ in enumerate(chunks))

audio = [bytes([128 + (30 if i % 3 else 0)] * 160) for i in range(9)]
speech = [c for c in audio if vad(c)]
print('chunks: %d, speech chunks: %d (VAD gated)' % (len(audio), len(speech)))
print('partial: "%s..." (streaming)' % decode(speech[:2]))
print('final: "%s" (on endpointing/silence)' % decode(speech))

# grammar-constrained recognition: tiny vocab, near-perfect accuracy
import re

grammar = [
    (r'scroll (up|down)', 'scroll'),
    (r'go back', 'back'),
    (r'set volume (\d+)', 'volume'),
    (r'open (\w+)', 'open'),
]

def recognize(text):
    for pat, cmd in grammar:
        m = re.fullmatch(pat, text.strip().lower())
        if m:
            return cmd, m.groups()
    return None, ()

for utter in ('scroll down', 'set volume 5', 'open mail', 'tell me a joke'):
    print('%-16r -> %s' % (utter, recognize(utter)))
print('the grammar IS the help screen: sayable = listed')

# intent + slots + confidence gating: act / confirm / ask
def nlu(text):
    t = text.lower()
    if 'light' in t:
        level = -20 if 'dim' in t or 'a bit' in t else 100
        return ('set_brightness', {'level': level}, 0.92)
    if 'timer' in t:
        return ('set_timer', {'minutes': 5}, 0.55)
    return (None, {}, 0.2)

for utter in ('dim the lights a bit', 'set a timer', 'blah blah'):
    intent, slots, conf = nlu(utter)
    action = 'ACT' if conf > 0.8 else 'CONFIRM' if conf > 0.4 else 'ASK'
    print('%-22r -> %s %s (conf %.2f)' % (utter, action, (intent, slots), conf))

# language ID per utterance, then the right grammar
def lang_id(text):
    es_words = {'pon', 'la', 'cancion', 'canción'}
    return 'es' if es_words & set(text.lower().split()) else 'en'

grammars = {'en': {'play': 'play music'}, 'es': {'pon': 'play music'}}

for utter in ('play some music', 'pon la canción'):
    lang = lang_id(utter)
    first = utter.lower().split()[0]
    print('%-16r lang=%s -> %s' % (utter, lang, grammars[lang].get(first, '?')))
print('code-switching ("pon la canción shake it off"): handle, never reject')
